1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
41	
42	export interface ScenarioResult {
43	  results: StepResult[];
44	}
45	
46	const PROCESSING_FEE = 5;
47	
48	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
49	  sword: 100,
50	  staff: 80,
51	  amulet: 60,
52	  potion: 40,
53	  rune: 25,
54	  moonstone: 25,
55	};
56	
57	const FIRST_INSURANCE_PERCENT = 10;
58	
59	// Surcharges are applied as (amount * percent) / 100 rather than via a decimal
60	// multiplier (e.g. * 1.1): the integer intermediate is exact, whereas 100 * 1.1
61	// is 110.00000000000001 in binary floating point. Since the final amount feeds
62	// straight into Math.ceil, that error would round a 115 G premium up to 116 G.
63	const percentOf = (amount: number, percent: number): number =>
64	  (amount * percent) / 100;
65	
66	const sum = (amounts: number[]): number =>
67	  amounts.reduce((total, amount) => total + amount, 0);
68	
69	/**
70	 * Reads a per-type rate table, rejecting types the MHPCO does not insure.
71	 *
72	 * The rate tables all share one domain — the insurable item types — so an
73	 * absent entry means the same thing in every one of them, and is reported the
74	 * same way. Keeping the guard here rather than at each call site is what stops
75	 * the tables from drifting into one validated and one silently yielding NaN.
76	 */
77	const rateFor = (table: Record<string, number>, itemType: string): number => {
78	  const rate = table[itemType];
79	  if (rate === undefined) {
80	    throw new Error(`The MHPCO does not insure items of type "${itemType}"`);
81	  }
82	  return rate;
83	};
84	
85	const itemBasePremium = (item: Item): number =>
86	  rateFor(BASE_PREMIUM_BY_TYPE, item.type);
87	
88	const BLOCK_SIZE = 3;
89	const BLOCK_BASE_PREMIUM = 60;
90	
91	const sumItemBasePremiums = (items: Item[]): number =>
92	  sum(items.map(itemBasePremium));
93	
94	/** Items of one and the same type, e.g. the three runes that form a block. */
95	type TypeGroup = Item[];
96	
97	const groupByType = (items: Item[]): TypeGroup[] => [
98	  ...items
99	    .reduce(
100	      (groups, item) =>
101	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
102	      new Map<string, TypeGroup>(),
103	    )
104	    .values(),
105	];
106	
107	const formsBlock = (group: TypeGroup): boolean => group.length === BLOCK_SIZE;
108	
109	const groupBasePremium = (group: TypeGroup): number =>
110	  formsBlock(group) ? BLOCK_BASE_PREMIUM : sumItemBasePremiums(group);
111	
112	const policyBasePremium = (items: Item[]): number =>
113	  sum(groupByType(items).map(groupBasePremium));
114	
115	const CURSE_PERCENT = 50;
116	const HIGH_ENCHANTMENT_PERCENT = 30;
117	const HIGH_ENCHANTMENT_THRESHOLD = 5;
118	
119	/**
120	 * A modifier adjusts a base premium by `percent` when it `applies` to its
121	 * subject. Discounts are expressed as negative percentages, so that the
122	 * applicable rules of one scope always combine by summation.
123	 */
124	interface ModifierRule<Subject> {
125	  applies: (subject: Subject) => boolean;
126	  percent: number;
127	}
128	
129	const applicablePercent = <Subject>(
130	  rules: ModifierRule<Subject>[],
131	  subject: Subject,
132	): number =>
133	  rules.reduce(
134	    (percent, rule) => (rule.applies(subject) ? percent + rule.percent : percent),
135	    0,
136	  );
137	
138	/**
139	 * Item-scoped modifiers apply to the affected item's own base premium, not to
140	 * the policy total.
141	 */
142	const ITEM_MODIFIER_RULES: ModifierRule<Item>[] = [
143	  { applies: (item) => item.cursed === true, percent: CURSE_PERCENT },
144	  {
145	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
146	    percent: HIGH_ENCHANTMENT_PERCENT,
147	  },
148	];
149	
150	const itemSurcharge = (item: Item): number =>
151	  percentOf(itemBasePremium(item), applicablePercent(ITEM_MODIFIER_RULES, item));
152	
153	const totalItemSurcharges = (items: Item[]): number =>
154	  sum(items.map(itemSurcharge));
155	
156	const LOYALTY_DISCOUNT_PERCENT = -20;
157	const LOYALTY_THRESHOLD_YEARS = 2;
158	const FOLLOW_UP_DISCOUNT_PERCENT = -15;
159	
160	/**
161	 * Everything a quote needs to know about the scenario around it: whose policy
162	 * this is, and how many quotes preceded it. Not the policy itself — it carries
163	 * no items, insurance sum or cap.
164	 */
165	interface QuoteContext {
166	  customer: Customer;
167	  precedingQuoteCount: number;
168	}
169	
170	/**
171	 * Policy-scoped modifiers apply to the policy base premium (the sum of all
172	 * item base premiums), independently of any item-scoped surcharges.
173	 */
174	const POLICY_MODIFIER_RULES: ModifierRule<QuoteContext>[] = [
175	  { applies: () => true, percent: FIRST_INSURANCE_PERCENT },
176	  {
177	    applies: ({ customer }) =>
178	      customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
179	    percent: LOYALTY_DISCOUNT_PERCENT,
180	  },
181	  {
182	    applies: ({ precedingQuoteCount }) => precedingQuoteCount > 0,
183	    percent: FOLLOW_UP_DISCOUNT_PERCENT,
184	  },
185	];
186	
187	const quotePremium = (step: QuoteStep, context: QuoteContext): number => {
188	  const basePremium = policyBasePremium(step.items);
189	  return Math.ceil(
190	    basePremium +
191	      percentOf(basePremium, applicablePercent(POLICY_MODIFIER_RULES, context)) +
192	      totalItemSurcharges(step.items) +
193	      PROCESSING_FEE,
194	  );
195	};
196	
197	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
198	  sword: 1000,
199	  staff: 800,
200	  amulet: 600,
201	  potion: 400,
202	  rune: 250,
203	  moonstone: 250,
204	};
205	
206	const DEDUCTIBLE = 100;
207	const CAP_MULTIPLE = 2;
208	
209	const itemInsuranceValue = (item: Item): number =>
210	  rateFor(INSURANCE_VALUE_BY_TYPE, item.type);
211	
212	const insuranceSum = (items: Item[]): number =>
213	  sum(items.map(itemInsuranceValue));
214	
215	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
216	const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
217	
218	/**
219	 * The share of a damage amount the MHPCO reimburses before the deductible.
220	 *
221	 * The spec's dragon-material clause ("fully reimbursed") is not a separate
222	 * branch here: full reimbursement is already the default, and where dragon
223	 * material meets enchantment >= 8 the spec says the 50 % rule wins. Dragon
224	 * material therefore never changes a payout, so encoding it would add a
225	 * branch no input can distinguish.
226	 */
227	const reimbursementPercent = (item: Item): number =>
228	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
229	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT
230	    : 100;
231	
232	const damagePayout = (damage: Damage, damagedItem: Item): number => {
233	  if (damage.amount < 0) {
234	    throw new Error(`A damage amount cannot be negative, got ${damage.amount}`);
235	  }
236	  return percentOf(damage.amount, reimbursementPercent(damagedItem)) - DEDUCTIBLE;
237	};
238	
239	/**
240	 * Pairs every damage entry with the insured item it refers to.
241	 *
242	 * Each entry consumes a distinct insured item, so a policy covering one sword
243	 * cannot absorb two sword damages. A damage the remaining cover cannot account
244	 * for — an uninsured type, an unknown type, or one damage too many — voids the
245	 * whole claim.
246	 */
247	const resolveDamagedItems = (insuredItems: Item[], damages: Damage[]): Item[] => {
248	  const unclaimed = [...insuredItems];
249	
250	  return damages.map((damage) => {
251	    const index = unclaimed.findIndex(
252	      (insured) => insured.type === damage.itemType,
253	    );
254	    if (index === -1) {
255	      throw new Error(
256	        `The policy does not cover a damage to an item of type "${damage.itemType}"`,
257	      );
258	    }
259	    return unclaimed.splice(index, 1)[0];
260	  });
261	};
262	
263	const totalPayout = (damages: Damage[], insuredItems: Item[]): number => {
264	  const damagedItems = resolveDamagedItems(insuredItems, damages);
265	  return Math.floor(
266	    sum(damages.map((damage, index) => damagePayout(damage, damagedItems[index]))),
267	  );
268	};
269	
270	/**
271	 * A claim pays what the damages come to, but never more than the policy's
272	 * remaining cap — successive claims against one policy draw down a shared
273	 * budget.
274	 */
275	const cappedPayout = (
276	  damages: Damage[],
277	  insuredItems: Item[],
278	  remainingCap: number,
279	): number => Math.min(totalPayout(damages, insuredItems), remainingCap);
280	
281	/**
282	 * The policy a claim refers to. A `policy` index is only meaningful if it
283	 * points at a quote step, so the lookup narrows rather than casts; the
284	 * `undefined` case is left for the error-handling tests to give meaning.
285	 */
286	const policyAt = (steps: Step[], index: number): QuoteStep | undefined => {
287	  const step = steps[index];
288	  return step?.op === "quote" ? step : undefined;
289	};
290	
291	/**
292	 * What a scenario accumulates as it runs: the remaining cap of every policy
293	 * quoted so far (keyed by the step index a claim names as its `policy`), and
294	 * how many quotes have been issued — the follow-up discount depends on it.
295	 */
296	class Ledger {
297	  private readonly remainingCapByPolicy = new Map<number, number>();
298	  quoteCount = 0;
299	
300	  openPolicy(policyIndex: number, items: Item[]): void {
301	    this.quoteCount++;
302	    this.remainingCapByPolicy.set(policyIndex, CAP_MULTIPLE * insuranceSum(items));
303	  }
304	
305	  /** Draws `payout` down from the policy's cap and reports what is left. */
306	  drawDown(policyIndex: number, payout: number): number {
307	    const remaining = this.remainingCap(policyIndex) - payout;
308	    this.remainingCapByPolicy.set(policyIndex, remaining);
309	    return remaining;
310	  }
311	
312	  remainingCap(policyIndex: number): number {
313	    return this.remainingCapByPolicy.get(policyIndex) ?? 0;
314	  }
315	}
316	
317	export const runScenario = (scenario: Scenario): ScenarioResult => {
318	  const ledger = new Ledger();
319	
320	  const runStep = (step: Step, index: number): StepResult => {
321	    if (step.op === "quote") {
322	      const context = {
323	        customer: scenario.customer,
324	        precedingQuoteCount: ledger.quoteCount,
325	      };
326	      ledger.openPolicy(index, step.items);
327	      return { premium: quotePremium(step, context) };
328	    }
329	
330	    const insuredItems = policyAt(scenario.steps, step.policy)?.items ?? [];
331	    const payout = cappedPayout(
332	      step.incident.damages,
333	      insuredItems,
334	      ledger.remainingCap(step.policy),
335	    );
336	    return { payout, remainingCap: ledger.drawDown(step.policy, payout) };
337	  };
338	
339	  return { results: scenario.steps.map(runStep) };
340	};
